/* =====================================================================
   app4_2_request_reads_test.sql   APP-4 stage 2: request reads test (queue, detail, notifications, dialog options, heater requests)
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/tests/t_request_reads.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app4_2_request_reads_test: 1 file(s) ===';

PRINT N'--- db/tests/t_request_reads.sql';
EXEC (N'/* =====================================================================
   t_request_reads.sql       APP-4 test: the read procedures behind the approval screens
                             (usp_request_queue, usp_request_detail, usp_notification_list, usp_request_form_options,
                              usp_equipment_requests and the function fn_request_actions)
   Needs : migrations 0001-0007, seeds 0101-0109, the APP-3 stage (request procedures and views) and the APP-4
           stage (app4_1_read_objects), and the SYNTHETIC gold stub (db/dev/gold_stub.sql). Skipped, with an
           INFO line, when the data engineer''s real gold has replaced the stub (the scenarios use the stub''s values).
   Needs no local seed: it makes its own people (addresses ending @example.test), memberships and eight requests
   INSIDE ONE TRANSACTION THAT IS ROLLED BACK AT THE END, so it leaves nothing behind (the last check proves it).
   Counts that depend on what is already in the database (other people''s requests) are compared as differences
   to a baseline taken first.
   Final line: `t_request_reads RESULT: ...`

   Scenarios
     Q1  the six tab counts follow a request through its life (create, approve, return, reject, final approval) for the
         responsible approver, the accountable approver, the requester and an outsider; approved and rejected are open
         to everybody
     Q2  rows of a tab: the right requests, oldest first with the request id as the last key, paging by offset without
         repeats, a page past the end is empty, the refusals (tab, page size, offset, age, actor)
     Q3  the filters (profit centre, field, rule, age, note) and the facets they are offered from; the age filter is ignored
         on the approved tab
     Q4  can_approve in the queue rows: yes for the eligible approver, yes for a member of both groups at the second
         stage (client, 18 Nov 2026), no for an outsider, no on closed requests
     Q5  the buttons agree with the procedures: every flag of fn_request_actions (can_decide, can_approve, can_resubmit,
         can_cancel, the return recipient) is proved against what usp_request_decide, _resubmit and _cancel really do
     Q6  the detail: the request row, its events in order, the related requests, the route, the golden record now,
         the six checks, a refused unknown request
     Q7  notifications: the unread count and the newest first list match the table, a read one is marked, bad inputs refused
     Q8  the request dialog''s options: list values, who may submit, which fields an ordinary person may not ask for
     Q9  the requests on a heater: its own and its location''s, open ones first; an unknown heater gives nothing
     Q10 the rollback left no test people, requests or notifications behind
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_request_reads wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.usp_request_queue'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_request_detail'', N''P'') IS NULL
   OR OBJECT_ID(N''app.usp_notification_list'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_request_form_options'', N''P'') IS NULL
   OR OBJECT_ID(N''app.usp_equipment_requests'', N''P'') IS NULL OR OBJECT_ID(N''app.fn_request_actions'', N''IF'') IS NULL
BEGIN
    PRINT ''FAIL t_request_reads a read procedure of the APP-4 stage is missing: run the bundle app4_1_read_objects first. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.usp_request_create'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_request_decide'', N''P'') IS NULL
   OR OBJECT_ID(N''app.usp_request_resubmit'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_request_cancel'', N''P'') IS NULL
   OR OBJECT_ID(N''app.vw_request_detail'', N''V'') IS NULL OR OBJECT_ID(N''app.vw_equipment_request'', N''V'') IS NULL
BEGIN
    PRINT ''FAIL t_request_reads the APP-3 request procedures or views are missing: run the APP-3 bundles first. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''gold.vw_equipment_current'', N''V'') IS NULL OR OBJECT_ID(N''gold.vw_equipment_field_current'', N''V'') IS NULL OR OBJECT_ID(N''gold.vw_floc_current'', N''V'') IS NULL
BEGIN
    PRINT ''FAIL t_request_reads the gold views are missing: run the gold stub (or the real gold) first. Nothing was run.'';
    RETURN;
END
IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_equipment_current'')) NOT LIKE N''%ATLAS-STUB%''
BEGIN
    PRINT ''INFO t_request_reads skipped: gold.vw_equipment_current is not the synthetic stub (the data engineer''''s real view?). The scenarios use the stub''''s values.'';
    RETURN;
END
IF NOT EXISTS (SELECT 1 FROM app.field_catalog WHERE field_code = N''EQUIPMENT_USER_STATUS'' AND allowed_values_source = N''LIST'')
   OR NOT EXISTS (SELECT 1 FROM app.app_setting WHERE setting_key = N''ADMIN_ONLY_FIELDS'')
BEGIN
    PRINT ''FAIL t_request_reads seeds 0108 / 0109 are missing: run bundle app3_0_seed_status first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;
DECLARE @txt nvarchar(2000), @errno int, @n int, @n2 int, @n3 int;
DECLARE @id bigint, @out nvarchar(24), @ns nvarchar(24), @nm bit;
DECLARE @eid int, @cur nvarchar(400);
DECLARE @a1 bigint, @a2 bigint, @a3 bigint, @a4 bigint, @a5 bigint, @a6 bigint, @a7 bigint, @a8 bigint;
DECLARE @pc nvarchar(40) = N''OP RES DB NM'', @pc_other nvarchar(40) = N''OP EOR'';
DECLARE @rg nvarchar(64), @ag nvarchar(64), @class nvarchar(30);

/* ---- the heaters the scenarios use: 8 synthetic filler heaters of one profit centre, with no open request ---- */
DECLARE @h TABLE (n int NOT NULL PRIMARY KEY, equipment_id int NOT NULL, equipment_number nvarchar(18) NOT NULL,
                  mfr nvarchar(30) NULL, model nvarchar(20) NULL, floc nvarchar(40) NOT NULL, equip_class nvarchar(30) NULL);
INSERT INTO @h (n, equipment_id, equipment_number, mfr, model, floc, equip_class)
SELECT ROW_NUMBER() OVER (ORDER BY e.equipment_id), e.equipment_id, e.equipment_number, e.manufacturer, e.model_number, e.functional_location, e.equip_class
FROM (SELECT TOP (8) x.*
      FROM gold.vw_equipment_current AS x
      WHERE x.profit_center_name = @pc AND x.equipment_number LIKE N''SYN-EQ-1%''
        AND NOT EXISTS (SELECT 1 FROM app.change_request AS r
                        WHERE r.equipment_id = x.equipment_id
                          AND r.request_status <> N''APPROVED'' AND r.request_status <> N''REJECTED'' AND r.request_status <> N''CANCELLED'')
      ORDER BY x.equipment_id) AS e;
SELECT @n = COUNT(*) FROM @h;
IF @n < 8
BEGIN
    PRINT ''FAIL t_request_reads setup: found '' + CAST(@n AS varchar(10)) + '' synthetic heaters without an open request in '' + @pc + '' (need 8). Reject or cancel the open requests on them, or rebuild the stub.'';
    RETURN;
END

/* ---- the routing the scenarios depend on -------------------------------------------- */
DECLARE @route TABLE (route_id int NULL, route_used nvarchar(12) NULL, responsible_role nvarchar(64) NULL,
                      responsible_group nvarchar(64) NULL, accountable_role nvarchar(64) NULL, accountable_group nvarchar(64) NULL);
SELECT @class = equip_class FROM @h WHERE n = 1;
INSERT INTO @route EXEC app.usp_route_resolve @entity_type = N''EQUIPMENT'', @request_action = N''UPDATE'', @profit_center_name = @pc, @field_code = N''MANUFACTURER'', @class_code = @class;
SELECT @rg = responsible_group, @ag = accountable_group FROM @route;
IF @rg IS NULL OR @ag IS NULL OR @rg = N''UNROUTED'' OR @ag = N''UNROUTED''
BEGIN
    PRINT ''FAIL t_request_reads setup: the route for '' + @pc + '' gives no groups (got '' + ISNULL(@rg, N''NULL'') + '', '' + ISNULL(@ag, N''NULL'') + ''). Run seeds 0103 to 0105.'';
    RETURN;
END

/* ---- people and memberships, all rolled back at the end --------------------------------- */
DECLARE @u_req nvarchar(256) = N''t4.requester@example.test'', @u_resp nvarchar(256) = N''t4.responsible@example.test'',
        @u_acc nvarchar(256) = N''t4.accountable@example.test'', @u_both nvarchar(256) = N''t4.both@example.test'',
        @u_none nvarchar(256) = N''t4.nobody@example.test'', @u_admin nvarchar(256) = N''t4.admin@example.test'',
        @u_unreg nvarchar(256) = N''t4.unregistered@example.test'';
DECLARE @setup_ok bit = 0;
BEGIN TRANSACTION;
BEGIN TRY
    INSERT INTO app.principal_identity (external_id, user_email, display_name, is_active, bound_by) VALUES
        (N''00000000-0000-4000-8000-0000000004a1'', @u_req,   N''T4 requester'',   1, N''test:t_request_reads''),
        (N''00000000-0000-4000-8000-0000000004a2'', @u_resp,  N''T4 responsible'', 1, N''test:t_request_reads''),
        (N''00000000-0000-4000-8000-0000000004a3'', @u_acc,   N''T4 accountable'', 1, N''test:t_request_reads''),
        (N''00000000-0000-4000-8000-0000000004a4'', @u_both,  N''T4 both stages'', 1, N''test:t_request_reads''),
        (N''00000000-0000-4000-8000-0000000004a5'', @u_none,  N''T4 nobody'',      1, N''test:t_request_reads''),
        (N''00000000-0000-4000-8000-0000000004a6'', @u_admin, N''T4 admin'',       1, N''test:t_request_reads'');
    INSERT INTO app.group_membership (group_key, user_email, is_active, added_by) VALUES
        (@rg, @u_resp, 1, N''test:t_request_reads''),
        (@rg, @u_both, 1, N''test:t_request_reads''),
        (@ag, @u_acc,  1, N''test:t_request_reads''),
        (@ag, @u_both, 1, N''test:t_request_reads'');
    INSERT INTO app.principal_role_assignment (principal_type, principal_key, principal_display_name, role_name, scope_type, scope_value, is_active)
    VALUES (N''USER'', @u_admin, N''T4 admin'', N''Admin'', N''ALL_ORCM'', NULL, 1);
    SET @setup_ok = 1;
END TRY
BEGIN CATCH
    PRINT ''FAIL t_request_reads setup error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;
IF @setup_ok = 0
BEGIN
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    RETURN;
END

/* ---- tables that catch the result sets (INSERT ... EXEC reads one set at a time: @only_set) --------------- */
DECLARE @q1 TABLE (responsible_count int, accountable_count int, returned_count int, approved_count int, rejected_count int, mine_count int);
DECLARE @q2 TABLE (total_matches int);
DECLARE @q3 TABLE (ord int IDENTITY(1,1) NOT NULL, request_id bigint, request_ref nvarchar(40), request_status nvarchar(40), approval_stage nvarchar(40),
    entity_type nvarchar(40), equipment_id int, equipment_number nvarchar(80), functional_location nvarchar(80), equipment_tag_number nvarchar(80),
    profit_center_name nvarchar(80), field_code nvarchar(80), field_label nvarchar(200), sap_field nvarchar(80), old_value nvarchar(400), new_value nvarchar(400),
    reason nvarchar(400), note nvarchar(400), source_type nvarchar(40), source_rule_id nvarchar(80), source_rule_version int, source_label nvarchar(200),
    requested_by nvarchar(300), requested_at_utc datetime2(3), detected_at_utc datetime2(3), responsible_group nvarchar(80), accountable_group nvarchar(80),
    return_recipient_type nvarchar(40), return_recipient nvarchar(300), age_hours int, photo_count int, updated_at_utc datetime2(3), can_approve bit);
DECLARE @q4 TABLE (facet_kind nvarchar(40), facet_value nvarchar(80), facet_label nvarchar(200), n int);
DECLARE @v TABLE (can_decide bit, decide_blocked_reason nvarchar(400), can_approve bit, approve_blocked_reason nvarchar(400),
    can_resubmit bit, can_cancel bit, return_to_type nvarchar(40), return_to nvarchar(300), return_to_label nvarchar(300), stage nvarchar(40),
    decided_as nvarchar(40));
DECLARE @d1 TABLE (request_id bigint, request_ref nvarchar(40), request_status nvarchar(40), approval_stage nvarchar(40),
    entity_type nvarchar(40), equipment_id int, equipment_number nvarchar(80), functional_location nvarchar(80), equipment_tag_number nvarchar(80),
    profit_center_name nvarchar(80), field_code nvarchar(80), field_label nvarchar(200), sap_field nvarchar(80), old_value nvarchar(400), new_value nvarchar(400),
    reason nvarchar(400), note nvarchar(400), source_type nvarchar(40), source_rule_id nvarchar(80), source_rule_version int, source_label nvarchar(200),
    requested_by nvarchar(300), requested_at_utc datetime2(3), detected_at_utc datetime2(3), responsible_group nvarchar(80), accountable_group nvarchar(80),
    return_recipient_type nvarchar(40), return_recipient nvarchar(300), age_hours int, photo_count int, updated_at_utc datetime2(3),
    class_code nvarchar(80), route_id int, creation_comment nvarchar(1000), last_decision_by nvarchar(300), last_decision_at_utc datetime2(3),
    merge_outcome nvarchar(40), merged_at_utc datetime2(3), golden_version_id int, exported_at_utc datetime2(3), evolve_batch_id bigint, evolve_row_number int);
DECLARE @d2 TABLE (ord int IDENTITY(1,1) NOT NULL, event_id bigint, event_type nvarchar(40), approval_stage nvarchar(40), actor nvarchar(300), actor_group nvarchar(80),
    occurred_at_utc datetime2(3), comments nvarchar(1000), status_from nvarchar(40), status_to nvarchar(40),
    decided_as nvarchar(40), same_person_both_stages bit, returned_to nvarchar(300));
DECLARE @d3 TABLE (ord int IDENTITY(1,1) NOT NULL, request_id bigint, request_ref nvarchar(40), request_status nvarchar(40), is_open bit, equipment_id int,
    functional_location nvarchar(80), field_code nvarchar(80), field_label nvarchar(200), source_label nvarchar(200), requested_at_utc datetime2(3), other_open int);
DECLARE @d4 TABLE (route_id int, entity_type nvarchar(40), request_action nvarchar(40), field_or_characteristic nvarchar(80), class_scope nvarchar(40), responsible_role nvarchar(80), accountable_role nvarchar(80));
DECLARE @d5 TABLE (entity_type nvarchar(40), equipment_number nvarchar(80), equipment_description nvarchar(200), equipment_tag_number nvarchar(80), functional_location nvarchar(80),
    floc_description nvarchar(200), equip_class nvarchar(80), profit_center_name nvarchar(80), manufacturer nvarchar(80), model_number nvarchar(80),
    manufacturer_serial_number nvarchar(80), equipment_user_status nvarchar(80), golden_version_id int, last_changed_at_utc datetime2(3),
    field_current_value nvarchar(400), field_unit nvarchar(40));
DECLARE @d6 TABLE (check_order int, check_code nvarchar(60), check_status nvarchar(20), message nvarchar(400), checked_at_utc datetime2(3));
DECLARE @nt1 TABLE (unread_count int);
DECLARE @nt2 TABLE (ord int IDENTITY(1,1) NOT NULL, notification_id bigint, topic nvarchar(60), request_id bigint, request_ref nvarchar(40), title nvarchar(400), body nvarchar(1000),
    created_at_utc datetime2(3), is_read bit);
DECLARE @f1 TABLE (field_code nvarchar(80), allowed_value nvarchar(100), display_order int);
DECLARE @f2 TABLE (can_submit bit, is_admin bit);
DECLARE @f3 TABLE (field_code nvarchar(80), reason nvarchar(300));
DECLARE @e1 TABLE (total_count int);
DECLARE @e2 TABLE (ord int IDENTITY(1,1) NOT NULL, request_id bigint, request_ref nvarchar(40), request_status nvarchar(40), is_open bit, equipment_id int,
    functional_location nvarchar(80), field_code nvarchar(80), field_label nvarchar(200), source_label nvarchar(200), requested_at_utc datetime2(3), other_open int);

/* counts, taken the same way many times */
DECLARE @c_resp int, @c_acc int, @c_ret int, @c_app int, @c_rej int, @c_mine int;       -- the counts of the person being looked at
DECLARE @b_resp_resp int, @b_resp_ret int, @b_acc_acc int, @b_acc_resp int, @b_req_mine int, @b_req_ret int, @b_app int, @b_rej int;

/* ---- baselines: what each person sees before the scenarios add anything ------------------------------------- */
DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @only_set = 1;
SELECT @b_resp_resp = responsible_count, @b_resp_ret = returned_count, @b_app = approved_count, @b_rej = rejected_count FROM @q1;
DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_acc, @tab = N''ACCOUNTABLE'', @only_set = 1;
SELECT @b_acc_acc = accountable_count, @b_acc_resp = responsible_count FROM @q1;
DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_req, @tab = N''MY_REQUESTS'', @only_set = 1;
SELECT @b_req_mine = mine_count, @b_req_ret = returned_count FROM @q1;

/* ---- the eight requests ----------------------------------------------------------------------------------------
   a1 heater 1 MANUFACTURER   goes all the way: responsible approve, accountable approve
   a2 heater 2 MANUFACTURER   returned to the requester, later resubmitted
   a3 heater 3 MANUFACTURER   rejected
   a4 heater 4 MANUFACTURER   stays at the responsible stage (made old for the age filter)
   a5 heater 5 MODEL_NUMBER   stays at the responsible stage (given the note TBD)
   a6 heater 6 MANUFACTURER   approved at stage 1 by the person who is in both groups (may also approve stage 2)
   a7 heater 7 MANUFACTURER   withdrawn by the requester
   a8 heater 1 MODEL_NUMBER   a second request on heater 1, stays at the responsible stage                              */
BEGIN TRY
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 1;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 1'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a1 = @id;
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 2;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 2'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a2 = @id;
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 3;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 3'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a3 = @id;
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 4;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 4'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a4 = @id;
    SELECT @eid = equipment_id, @cur = model FROM @h WHERE n = 5;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MODEL_NUMBER'', @new_value = N''T4 MDL 5'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a5 = @id;
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 6;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 6'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a6 = @id;
    SELECT @eid = equipment_id, @cur = mfr FROM @h WHERE n = 7;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MANUFACTURER'', @new_value = N''T4 MFR 7'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a7 = @id;
    SELECT @eid = equipment_id, @cur = model FROM @h WHERE n = 1;
    EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''MODEL_NUMBER'', @new_value = N''T4 MDL 8'',
        @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0, @o_request_id = @id OUTPUT;
    SET @a8 = @id;
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL setup the eight requests could not be created, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT ''t_request_reads RESULT: setup failed, nothing else was run'';
    RETURN;
END CATCH;

/* ---- Q1 (first half) the counts after the requests were made ---------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @only_set = 1;
    SELECT @c_resp = responsible_count, @c_acc = accountable_count, @c_mine = mine_count FROM @q1;
    IF @c_resp <> @b_resp_resp + 8 SET @txt += N'' the responsible approver sees '' + CAST(@c_resp AS nvarchar(10)) + N'' (expected '' + CAST(@b_resp_resp + 8 AS nvarchar(10)) + N'');'';
    IF @c_mine <> 0 SET @txt += N'' the responsible approver has '' + CAST(@c_mine AS nvarchar(10)) + N'' requests of their own (expected 0);'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_acc, @tab = N''ACCOUNTABLE'', @only_set = 1;
    SELECT @c_resp = responsible_count, @c_acc = accountable_count FROM @q1;
    IF @c_acc <> @b_acc_acc SET @txt += N'' the accountable approver sees '' + CAST(@c_acc AS nvarchar(10)) + N'' (expected '' + CAST(@b_acc_acc AS nvarchar(10)) + N'', nothing waits for them yet);'';
    IF @c_resp <> @b_acc_resp SET @txt += N'' the accountable approver sees '' + CAST(@c_resp AS nvarchar(10)) + N'' at the responsible stage (expected '' + CAST(@b_acc_resp AS nvarchar(10)) + N'', their group has nothing new there);'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_req, @tab = N''MY_REQUESTS'', @only_set = 1;
    SELECT @c_mine = mine_count, @c_resp = responsible_count FROM @q1;
    IF @c_mine <> @b_req_mine + 8 SET @txt += N'' the requester has '' + CAST(@c_mine AS nvarchar(10)) + N'' requests (expected '' + CAST(@b_req_mine + 8 AS nvarchar(10)) + N'');'';
    IF @c_resp <> 0 SET @txt += N'' the requester sees '' + CAST(@c_resp AS nvarchar(10)) + N'' in the responsible tab;'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_none, @tab = N''MY_REQUESTS'', @only_set = 1;
    SELECT @c_resp = responsible_count, @c_acc = accountable_count, @c_ret = returned_count, @c_mine = mine_count FROM @q1;
    IF @c_resp <> 0 OR @c_acc <> 0 OR @c_ret <> 0 OR @c_mine <> 0 SET @txt += N'' an outsider sees queue items ('' + CAST(@c_resp AS nvarchar(10)) + N''/'' + CAST(@c_acc AS nvarchar(10)) + N''/'' + CAST(@c_ret AS nvarchar(10)) + N''/'' + CAST(@c_mine AS nvarchar(10)) + N'');'';
    IF @txt = N'''' PRINT ''OK  Q1a after eight new requests: the responsible approver +8, the accountable approver +0, the requester +8 of their own, an outsider nothing'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q1a'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q1a error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q5 (first half) the buttons agree with the decision procedure, while the requests move on ------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    -- an outsider to the group: the screen says no, the procedure refuses with the matching number
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a4, @actor_email = @u_acc, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 0 AND can_approve = 0 AND decide_blocked_reason LIKE N''You are not an active member of the group%'' AND approve_blocked_reason = decide_blocked_reason;
    IF @n <> 1 SET @txt += N'' an approver of another group should be told they are not a member;'';
    SET @errno = NULL;
    BEGIN TRY
        EXEC app.usp_request_decide @request_id = @a4, @actor_email = @u_acc, @decision = N''APPROVE'', @emit_result = 0;
    END TRY
    BEGIN CATCH
        SET @errno = ERROR_NUMBER();
    END CATCH;
    IF @errno IS NULL OR @errno <> 50141 SET @txt += N'' the procedure gave error '' + ISNULL(CAST(@errno AS nvarchar(12)), N''none'') + N'' to that person (expected 50141);'';
    -- a blank and a system actor: no rights, with a plain sentence
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a4, @actor_email = N''system:rule-run'', @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 0 AND can_approve = 0 AND can_resubmit = 0 AND can_cancel = 0 AND decide_blocked_reason = N''Sign in as a person to decide.'';
    IF @n <> 1 SET @txt += N'' a system address must get no rights;'';
    -- the eligible approver: yes to everything at stage 1; the return recipient is the requester, shown by name
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_resp, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 1 AND can_approve = 1 AND decide_blocked_reason IS NULL AND approve_blocked_reason IS NULL
                                    AND stage = N''RESPONSIBLE'' AND return_to_type = N''USER'' AND return_to = @u_req AND return_to_label = N''T4 requester''
                                    AND can_resubmit = 0 AND can_cancel = 0;
    IF @n <> 1 SET @txt += N'' the responsible approver should be able to decide and approve, with a return to the requester by name, and be unable to resubmit or withdraw;'';
    EXEC app.usp_request_decide @request_id = @a1, @actor_email = @u_resp, @decision = N''APPROVE'', @comment = N''T4 stage 1'', @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
    IF @ns <> N''PENDING_ACCOUNTABLE'' SET @txt += N'' the approval the screen allowed gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    -- stage 2 for the accountable approver: yes; for the one who did stage 1: reject yes, approve no (segregation)
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_acc, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 1 AND can_approve = 1 AND stage = N''ACCOUNTABLE'';
    IF @n <> 1 SET @txt += N'' the accountable approver should be able to approve at stage 2;'';
    -- a6: the person in both groups does stage 1, and may also approve stage 2 (client, 18 Nov 2026; Q-479).
    -- The flag is checked here; the approval itself is proved in t_request_lifecycle S7 (a6 stays pending for Q4).
    EXEC app.usp_request_decide @request_id = @a6, @actor_email = @u_both, @decision = N''APPROVE'', @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a6, @actor_email = @u_both, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 1 AND decide_blocked_reason IS NULL AND can_approve = 1 AND approve_blocked_reason IS NULL AND decided_as = N''GROUP_MEMBER'';
    IF @n <> 1 SET @txt += N'' the person in both groups who did stage 1 should be allowed to approve stage 2 too;'';
    -- the person in the first group only may not (the screen says so, the procedure refuses with 50141)
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a6, @actor_email = @u_resp, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 0 AND can_approve = 0 AND decide_blocked_reason LIKE N''You are not an active member of the group%'';
    IF @n <> 1 SET @txt += N'' a first-group-only approver should be told they are not a member at stage 2;'';
    SET @errno = NULL;
    BEGIN TRY
        EXEC app.usp_request_decide @request_id = @a6, @actor_email = @u_resp, @decision = N''APPROVE'', @emit_result = 0;
    END TRY
    BEGIN CATCH
        SET @errno = ERROR_NUMBER();
    END CATCH;
    IF @errno IS NULL OR @errno <> 50141 SET @txt += N'' the procedure gave error '' + ISNULL(CAST(@errno AS nvarchar(12)), N''none'') + N'' to a first-group-only approver at stage 2 (expected 50141);'';
    -- a2 is returned (the screen allowed it), a3 is rejected (the screen allowed it)
    EXEC app.usp_request_decide @request_id = @a2, @actor_email = @u_resp, @decision = N''RETURN'', @comment = N''T4 please check'', @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
    IF @ns <> N''RETURNED'' SET @txt += N'' the return gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    EXEC app.usp_request_decide @request_id = @a3, @actor_email = @u_resp, @decision = N''REJECT'', @comment = N''T4 not right'', @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
    IF @ns <> N''REJECTED'' SET @txt += N'' the rejection gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    -- (a6 is left pending: it is used below for the queue rows)
    IF @txt = N'''' PRINT ''OK  Q5a decide: an outsider, a system address, the eligible approver, the member of both groups at stage 2 and a first-group-only approver at stage 2 are told what the procedure then does (50141, approve, return, reject)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q5a'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q5a error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q1 (second half) the counts after approve, return, reject --------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @only_set = 1;
    SELECT @c_resp = responsible_count, @c_rej = rejected_count FROM @q1;
    -- 8 created; a1 and a6 moved to stage 2, a2 returned, a3 rejected: a4, a5, a7, a8 are left
    IF @c_resp <> @b_resp_resp + 4 SET @txt += N'' the responsible approver sees '' + CAST(@c_resp AS nvarchar(10)) + N'' (expected '' + CAST(@b_resp_resp + 4 AS nvarchar(10)) + N'');'';
    IF @c_rej <> @b_rej + 1 SET @txt += N'' rejected is '' + CAST(@c_rej AS nvarchar(10)) + N'' (expected '' + CAST(@b_rej + 1 AS nvarchar(10)) + N'');'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_acc, @tab = N''ACCOUNTABLE'', @only_set = 1;
    SELECT @c_acc = accountable_count, @c_rej = rejected_count FROM @q1;
    IF @c_acc <> @b_acc_acc + 2 SET @txt += N'' the accountable approver sees '' + CAST(@c_acc AS nvarchar(10)) + N'' (expected '' + CAST(@b_acc_acc + 2 AS nvarchar(10)) + N'': a1 and a6);'';
    IF @c_rej <> @b_rej + 1 SET @txt += N'' rejected is not open to the accountable approver too ('' + CAST(@c_rej AS nvarchar(10)) + N'');'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_req, @tab = N''RETURNED'', @only_set = 1;
    SELECT @c_ret = returned_count, @c_mine = mine_count FROM @q1;
    IF @c_ret <> @b_req_ret + 1 SET @txt += N'' the requester has '' + CAST(@c_ret AS nvarchar(10)) + N'' returned requests (expected '' + CAST(@b_req_ret + 1 AS nvarchar(10)) + N'');'';
    IF @c_mine <> @b_req_mine + 8 SET @txt += N'' the requester has '' + CAST(@c_mine AS nvarchar(10)) + N'' of their own (expected '' + CAST(@b_req_mine + 8 AS nvarchar(10)) + N'');'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RETURNED'', @only_set = 1;
    SELECT @c_ret = returned_count FROM @q1;
    IF @c_ret <> @b_resp_ret SET @txt += N'' the approver who returned it sees it in their Returned tab ('' + CAST(@c_ret AS nvarchar(10)) + N'' against '' + CAST(@b_resp_ret AS nvarchar(10)) + N'' before);'';
    -- the returned request, as a row of the requester''s Returned tab, carries who it went to
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_req, @tab = N''RETURNED'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a2 AND request_status = N''RETURNED'' AND return_recipient_type = N''USER'' AND return_recipient = @u_req AND can_approve = 0;
    IF @n <> 1 SET @txt += N'' the returned request is not a row of the requester''''s Returned tab with its recipient;'';
    IF @txt = N'''' PRINT ''OK  Q1b after approve, return and reject: stage-1 queue -4, stage-2 queue +2, rejected +1 for everybody, the requester''''s Returned tab +1 and not the returner''''s'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q1b'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q1b error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q1 (third part) the final approval, approved is open to everybody ------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    EXEC app.usp_request_decide @request_id = @a1, @actor_email = @u_acc, @decision = N''APPROVE'', @comment = N''T4 stage 2'', @emit_result = 0, @o_new_status = @ns OUTPUT, @o_needs_merge = @nm OUTPUT;
    IF @ns <> N''APPROVED'' OR @nm <> 1 SET @txt += N'' the final approval gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_none, @tab = N''APPROVED'', @only_set = 1;
    SELECT @c_app = approved_count FROM @q1;
    IF @c_app <> @b_app + 1 SET @txt += N'' an outsider sees '' + CAST(@c_app AS nvarchar(10)) + N'' approved (expected '' + CAST(@b_app + 1 AS nvarchar(10)) + N'');'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_none, @tab = N''APPROVED'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a1 AND request_status = N''APPROVED'' AND approval_stage IS NULL AND age_hours IS NULL AND can_approve = 0
                                     AND field_code = N''MANUFACTURER'' AND field_label IS NOT NULL AND source_label = N''Manual request'' AND new_value = N''T4 MFR 1'';
    IF @n <> 1 SET @txt += N'' the approved request is not in an outsider''''s Approved tab as a closed row (no stage, no age, cannot be approved);'';
    DELETE FROM @q1; INSERT INTO @q1 EXEC app.usp_request_queue @actor_email = @u_acc, @tab = N''ACCOUNTABLE'', @only_set = 1;
    SELECT @c_acc = accountable_count FROM @q1;
    IF @c_acc <> @b_acc_acc + 1 SET @txt += N'' the accountable approver sees '' + CAST(@c_acc AS nvarchar(10)) + N'' after the final approval (expected '' + CAST(@b_acc_acc + 1 AS nvarchar(10)) + N'');'';
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_acc, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_decide = 0 AND can_approve = 0 AND decide_blocked_reason LIKE N''The request is APPROVED%'' AND stage IS NULL AND return_to IS NULL;
    IF @n <> 1 SET @txt += N'' an approved request should show that it cannot be decided any more;'';
    IF @txt = N'''' PRINT ''OK  Q1c final approval: approved is +1 for an outsider and shown as a closed row; the accountable queue shrinks by one; the screen says the request is closed'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q1c'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q1c error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q2 rows of a tab, order, paging, refusals ------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a4, @a5, @a7, @a8);
    SELECT @n2 = COUNT(*) FROM @q3 WHERE request_id IN (@a1, @a2, @a3, @a6);
    IF @n <> 4 OR @n2 <> 0 SET @txt += N'' the responsible tab holds '' + CAST(@n AS nvarchar(10)) + N'' of the four waiting requests and '' + CAST(@n2 AS nvarchar(10)) + N'' that moved on;'';
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a4 AND request_status = N''PENDING_RESPONSIBLE'' AND approval_stage = N''RESPONSIBLE'' AND entity_type = N''EQUIPMENT''
        AND profit_center_name = @pc AND field_code = N''MANUFACTURER'' AND field_label = N''Manufacturer'' AND new_value = N''T4 MFR 4'' AND reason = N''T4 reads''
        AND source_type = N''MANUAL'' AND source_label = N''Manual request'' AND requested_by = @u_req AND responsible_group = @rg AND accountable_group = @ag
        AND photo_count = 0 AND age_hours IS NOT NULL AND detected_at_utc IS NULL;
    IF @n <> 1 SET @txt += N'' the row of a waiting request lacks its display columns;'';
    -- order: oldest first, the request id last (a4, a5, a7, a8 were made in that order)
    SELECT @n = COUNT(*) FROM @q3 AS x JOIN @q3 AS y ON x.request_id IN (@a4, @a5, @a7, @a8) AND y.request_id IN (@a4, @a5, @a7, @a8) AND x.request_id < y.request_id AND x.ord > y.ord;
    IF @n <> 0 SET @txt += N'' '' + CAST(@n AS nvarchar(10)) + N'' pairs of waiting requests are in the wrong order (oldest first, then the request id);'';
    SELECT @n = COUNT(*) FROM @q3 AS x JOIN @q3 AS y ON x.ord + 1 = y.ord WHERE x.requested_at_utc > y.requested_at_utc;
    IF @n <> 0 SET @txt += N'' the responsible tab is not ordered oldest first ('' + CAST(@n AS nvarchar(10)) + N'' steps go backwards);'';
    SELECT @n = COUNT(*) FROM @q3;
    DELETE FROM @q2; INSERT INTO @q2 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @page_size = 100, @only_set = 2;
    SELECT @n2 = total_matches FROM @q2;
    IF (@n < 100 AND @n2 <> @n) OR @n2 <> @b_resp_resp + 4 SET @txt += N'' total_matches is '' + CAST(@n2 AS nvarchar(10)) + N'' for '' + CAST(@n AS nvarchar(10)) + N'' rows (expected '' + CAST(@b_resp_resp + 4 AS nvarchar(10)) + N'');'';
    -- paging by offset: pages of one row do not repeat, the first equals the top of the full list, a page past the end is empty
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @offset = 0, @page_size = 1, @only_set = 3;
    SELECT TOP (1) @id = request_id FROM @q3 ORDER BY ord;
    SELECT @n = COUNT(*) FROM @q3;
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @offset = 1, @page_size = 1, @only_set = 3;
    SELECT @n2 = COUNT(*) FROM @q3 WHERE request_id <> @id;
    IF @n <> 1 OR @n2 <> 1 SET @txt += N'' two pages of one row should be two different rows ('' + CAST(@n AS nvarchar(10)) + N'', '' + CAST(@n2 AS nvarchar(10)) + N'');'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @offset = 100000, @page_size = 10, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3;
    IF @n <> 0 SET @txt += N'' a page past the end returned '' + CAST(@n AS nvarchar(10)) + N'' rows;'';
    -- the closed tabs run newest change first: the rejected a3 comes before the approved a1 only within their own tab, so check the Approved tab''s order
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''APPROVED'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 AS x JOIN @q3 AS y ON x.ord + 1 = y.ord WHERE x.updated_at_utc < y.updated_at_utc;
    SELECT TOP (1) @id = request_id FROM @q3 ORDER BY ord;
    IF @n <> 0 OR @id <> @a1 SET @txt += N'' the Approved tab should list the newest change first (top is request '' + ISNULL(CAST(@id AS nvarchar(20)), N''none'') + N'', '' + CAST(@n AS nvarchar(10)) + N'' steps go the wrong way);'';
    -- the refusals
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''EVERYTHING'', @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50311 SET @txt += N'' an unknown tab gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50311);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @page_size = 0, @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50312 SET @txt += N'' page size 0 gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50312);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @page_size = 101, @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50312 SET @txt += N'' page size 101 gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50312);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @offset = -1, @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50313 SET @txt += N'' a negative offset gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50313);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @min_age_hours = -5, @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50314 SET @txt += N'' a negative age gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50314);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_queue @actor_email = N''system:rule-run'', @tab = N''RESPONSIBLE'', @only_set = 2; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50315 SET @txt += N'' a system address gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50315);'';
    IF @txt = N'''' PRINT ''OK  Q2 the responsible tab holds exactly the waiting requests, oldest first with the id last; paging by offset repeats nothing; a page past the end is empty; the Approved tab runs newest first; six refusals'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q2'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q2 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q3 the filters and the facets -------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    -- make a4 old (48 hours) and give a5 a note, inside the test transaction
    UPDATE app.change_request SET requested_at_utc = DATEADD(hour, -48, SYSUTCDATETIME()) WHERE request_id = @a4;
    UPDATE app.change_request SET note = N''TBD'' WHERE request_id = @a5;

    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @field_code = N''MODEL_NUMBER'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a5, @a8);
    SELECT @n2 = COUNT(*) FROM @q3 WHERE field_code <> N''MODEL_NUMBER'' OR request_id IN (@a4, @a7);
    IF @n <> 2 OR @n2 <> 0 SET @txt += N'' the field filter kept '' + CAST(@n AS nvarchar(10)) + N'' of the two MODEL_NUMBER requests and '' + CAST(@n2 AS nvarchar(10)) + N'' other rows;'';

    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @profit_center = @pc, @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a4, @a5, @a7, @a8);
    SELECT @n2 = COUNT(*) FROM @q3 WHERE profit_center_name <> @pc;
    IF @n <> 4 OR @n2 <> 0 SET @txt += N'' the profit-centre filter kept '' + CAST(@n AS nvarchar(10)) + N'' of four and let '' + CAST(@n2 AS nvarchar(10)) + N'' rows of other centres through;'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @profit_center = @pc_other, @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a4, @a5, @a7, @a8) OR profit_center_name <> @pc_other;
    IF @n <> 0 SET @txt += N'' the filter for another centre still lists our requests or rows of other centres ('' + CAST(@n AS nvarchar(10)) + N'');'';

    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @note_only = 1, @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a5 AND note = N''TBD'';
    SELECT @n2 = COUNT(*) FROM @q3 WHERE note IS NULL OR request_id IN (@a4, @a7, @a8);
    IF @n <> 1 OR @n2 <> 0 SET @txt += N'' the note filter kept '' + CAST(@n AS nvarchar(10)) + N'' TBD request and '' + CAST(@n2 AS nvarchar(10)) + N'' without a note;'';

    DELETE FROM @q2; INSERT INTO @q2 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @rule_id = N''T4_NO_SUCH_RULE'', @only_set = 2;
    SELECT @n = total_matches FROM @q2;
    IF @n <> 0 SET @txt += N'' a rule that raised nothing still matched '' + CAST(@n AS nvarchar(10)) + N'' requests;'';

    -- the age filter: a4 is 48 hours old, the others are new; it keeps open requests only
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @min_age_hours = 24, @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a4 AND age_hours >= 47;
    SELECT @n2 = COUNT(*) FROM @q3 WHERE request_id IN (@a5, @a7, @a8) OR age_hours < 24;
    IF @n <> 1 OR @n2 <> 0 SET @txt += N'' the 24-hour filter kept '' + CAST(@n AS nvarchar(10)) + N'' of the old request and '' + CAST(@n2 AS nvarchar(10)) + N'' new ones;'';
    DELETE FROM @q2; INSERT INTO @q2 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @min_age_hours = 72, @only_set = 2;
    SELECT @n = total_matches FROM @q2;
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @min_age_hours = 72, @page_size = 100, @only_set = 3;
    SELECT @n2 = COUNT(*) FROM @q3 WHERE request_id = @a4;
    IF @n2 <> 0 SET @txt += N'' a 72-hour filter still lists the 48-hour-old request;'';
    -- on the Approved tab the age filter is ignored (a closed request has no age)
    DELETE FROM @q2; INSERT INTO @q2 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''APPROVED'', @only_set = 2;
    SELECT @n = total_matches FROM @q2;
    DELETE FROM @q2; INSERT INTO @q2 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''APPROVED'', @min_age_hours = 72, @only_set = 2;
    SELECT @n2 = total_matches FROM @q2;
    IF @n <> @n2 OR @n < 1 SET @txt += N'' the age filter changed the Approved tab ('' + CAST(@n AS nvarchar(10)) + N'' without it, '' + CAST(@n2 AS nvarchar(10)) + N'' with it);'';

    -- the facets list what the tab holds, whatever the filters say
    DELETE FROM @q4; INSERT INTO @q4 EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @field_code = N''MODEL_NUMBER'', @only_set = 4;
    SELECT @n = COUNT(*) FROM @q4 WHERE facet_kind = N''PROFIT_CENTER'' AND facet_value = @pc AND n >= 4;
    SELECT @n2 = COUNT(*) FROM @q4 WHERE facet_kind = N''FIELD'' AND facet_value = N''MANUFACTURER'' AND facet_label = N''Manufacturer'' AND n >= 2;
    SELECT @n3 = COUNT(*) FROM @q4 WHERE facet_kind = N''FIELD'' AND facet_value = N''MODEL_NUMBER'' AND n >= 2;
    IF @n <> 1 OR @n2 <> 1 OR @n3 <> 1 SET @txt += N'' the facets are wrong: profit centre '' + CAST(@n AS nvarchar(10)) + N'', manufacturer '' + CAST(@n2 AS nvarchar(10)) + N'', model '' + CAST(@n3 AS nvarchar(10)) + N'' (each should be 1, even with a field filter set);'';
    IF @txt = N'''' PRINT ''OK  Q3 filters: field, profit centre, note, rule and age each narrow the responsible tab as asked; the age filter is ignored on the Approved tab; the facets list what the tab holds even while a filter is set'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q3'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q3 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q4 can_approve in the queue rows ------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_resp, @tab = N''RESPONSIBLE'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a4, @a5, @a7, @a8) AND can_approve = 1;
    IF @n <> 4 SET @txt += N'' the responsible approver can tick '' + CAST(@n AS nvarchar(10)) + N'' of the four waiting requests (expected 4);'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_acc, @tab = N''ACCOUNTABLE'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a6 AND can_approve = 1 AND approval_stage = N''ACCOUNTABLE'';
    IF @n <> 1 SET @txt += N'' the accountable approver cannot approve a6 at stage 2;'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_both, @tab = N''ACCOUNTABLE'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id = @a6 AND can_approve = 1;
    IF @n <> 1 SET @txt += N'' the person in both groups who did stage 1 of a6 cannot tick it at stage 2 (allowed since 18 Nov);'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_none, @tab = N''APPROVED'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE can_approve = 1;
    IF @n <> 0 SET @txt += N'' '' + CAST(@n AS nvarchar(10)) + N'' closed requests can be ticked for approval;'';
    DELETE FROM @q3; INSERT INTO @q3 (request_id, request_ref, request_status, approval_stage, entity_type, equipment_id, equipment_number, functional_location, equipment_tag_number,
        profit_center_name, field_code, field_label, sap_field, old_value, new_value, reason, note, source_type, source_rule_id, source_rule_version, source_label, requested_by,
        requested_at_utc, detected_at_utc, responsible_group, accountable_group, return_recipient_type, return_recipient, age_hours, photo_count, updated_at_utc, can_approve)
        EXEC app.usp_request_queue @actor_email = @u_req, @tab = N''MY_REQUESTS'', @page_size = 100, @only_set = 3;
    SELECT @n = COUNT(*) FROM @q3 WHERE request_id IN (@a1, @a2, @a3, @a4, @a5, @a6, @a7, @a8);
    SELECT @n2 = COUNT(*) FROM @q3 WHERE can_approve = 1;
    IF @n <> 8 OR @n2 <> 0 SET @txt += N'' the requester''''s own tab lists '' + CAST(@n AS nvarchar(10)) + N'' of the eight requests and '' + CAST(@n2 AS nvarchar(10)) + N'' that they could approve;'';
    IF @txt = N'''' PRINT ''OK  Q4 can_approve: the eligible approver yes, the member of both groups at stage 2 yes, an outsider no, closed requests no, the requester''''s own list lists all eight with none tickable'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q4'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q4 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q5 (second half) resubmit and withdraw: the flags agree with the procedures ------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    -- a2 is RETURNED to the requester: only they may resubmit or withdraw
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a2, @actor_email = @u_req, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_resubmit = 1 AND can_cancel = 1 AND can_decide = 0 AND can_approve = 0 AND return_to_type = N''USER'' AND return_to = @u_req;
    IF @n <> 1 SET @txt += N'' the requester of a returned request should be able to resubmit and withdraw but not decide;'';
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a2, @actor_email = @u_resp, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_resubmit = 0 AND can_cancel = 0;
    IF @n <> 1 SET @txt += N'' the approver who returned it should be unable to resubmit or withdraw it;'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_resubmit @request_id = @a2, @actor_email = @u_resp, @emit_result = 0; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50163 SET @txt += N'' the procedure let the wrong person resubmit ('' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'', expected 50163);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_cancel @request_id = @a2, @actor_email = @u_resp, @emit_result = 0; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50173 SET @txt += N'' the procedure let the wrong person withdraw ('' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'', expected 50173);'';
    EXEC app.usp_request_resubmit @request_id = @a2, @actor_email = @u_req, @emit_result = 0, @o_new_status = @ns OUTPUT;
    IF @ns <> N''PENDING_RESPONSIBLE'' SET @txt += N'' the resubmission the screen allowed gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a2, @actor_email = @u_req, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_resubmit = 0 AND can_cancel = 1 AND stage = N''RESPONSIBLE'';
    IF @n <> 1 SET @txt += N'' after resubmitting, the requester should still be able to withdraw but not resubmit again;'';
    -- a7: the requester may withdraw an open request, the approver may not; afterwards nobody may
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a7, @actor_email = @u_resp, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_cancel = 0;
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a7, @actor_email = @u_req, @only_set = 7;
    SELECT @n2 = COUNT(*) FROM @v WHERE can_cancel = 1;
    IF @n <> 1 OR @n2 <> 1 SET @txt += N'' withdraw flags are wrong for a7 (approver '' + CAST(@n AS nvarchar(10)) + N'', requester '' + CAST(@n2 AS nvarchar(10)) + N'');'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_cancel @request_id = @a7, @actor_email = @u_resp, @emit_result = 0; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50173 SET @txt += N'' an approver could withdraw a7 ('' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'');'';
    EXEC app.usp_request_cancel @request_id = @a7, @actor_email = @u_req, @emit_result = 0, @o_new_status = @ns OUTPUT;
    IF @ns <> N''CANCELLED'' SET @txt += N'' the withdrawal the screen allowed gave '' + ISNULL(@ns, N''NULL'') + N'';'';
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a7, @actor_email = @u_req, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_cancel = 0 AND can_decide = 0 AND stage IS NULL;
    IF @n <> 1 SET @txt += N'' a withdrawn request should offer nothing;'';
    -- a3 was rejected, a1 approved: nothing to decide, nothing to withdraw
    DELETE FROM @v; INSERT INTO @v EXEC app.usp_request_detail @request_id = @a3, @actor_email = @u_req, @only_set = 7;
    SELECT @n = COUNT(*) FROM @v WHERE can_cancel = 0 AND can_resubmit = 0 AND can_decide = 0;
    IF @n <> 1 SET @txt += N'' a rejected request should offer nothing;'';
    IF @txt = N'''' PRINT ''OK  Q5b resubmit and withdraw: the returned request''''s requester may resubmit and withdraw, the returner may not (50163, 50173 confirm), a withdrawn or rejected request offers nothing'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q5b'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q5b error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q6 the detail ------------------------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    -- a1: approved, with three events
    DELETE FROM @d1; INSERT INTO @d1 EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_resp, @only_set = 1;
    SELECT @n = COUNT(*) FROM @d1 WHERE request_id = @a1 AND request_status = N''APPROVED'' AND creation_comment IS NULL AND route_id IS NOT NULL;
    IF @n <> 1 SET @txt += N'' the request row is wrong;'';
    DELETE FROM @d2; INSERT INTO @d2 (event_id, event_type, approval_stage, actor, actor_group, occurred_at_utc, comments, status_from, status_to,
                                      decided_as, same_person_both_stages, returned_to)
        EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_resp, @only_set = 2;
    SELECT @n = COUNT(*) FROM @d2;
    SELECT @n2 = COUNT(*) FROM @d2 WHERE (ord = 1 AND event_type = N''CREATED'' AND actor = @u_req AND status_to = N''PENDING_RESPONSIBLE'')
                                       OR (ord = 2 AND event_type = N''RESPONSIBLE_APPROVED'' AND actor = @u_resp AND actor_group = @rg AND comments = N''T4 stage 1'')
                                       OR (ord = 3 AND event_type = N''ACCOUNTABLE_APPROVED'' AND actor = @u_acc AND actor_group = @ag AND status_to = N''APPROVED'');
    IF @n <> 3 OR @n2 <> 3 SET @txt += N'' the history of a1 should be CREATED, RESPONSIBLE_APPROVED, ACCOUNTABLE_APPROVED in order (got '' + CAST(@n AS nvarchar(10)) + N'' events, '' + CAST(@n2 AS nvarchar(10)) + N'' as expected);'';
    -- related: a1 and a8 share heater 1 (different fields), so each sees the other and nothing else of ours
    DELETE FROM @d3; INSERT INTO @d3 (request_id, request_ref, request_status, is_open, equipment_id, functional_location, field_code, field_label, source_label, requested_at_utc, other_open)
        EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_resp, @only_set = 3;
    SELECT @n = COUNT(*) FROM @d3 WHERE request_id = @a8 AND request_status = N''PENDING_RESPONSIBLE'' AND is_open = 1 AND field_code = N''MODEL_NUMBER'' AND source_label = N''Manual request'';
    SELECT @n2 = COUNT(*) FROM @d3 WHERE request_id = @a1 OR request_id IN (@a2, @a3, @a4, @a5, @a6, @a7);
    IF @n <> 1 OR @n2 <> 0 SET @txt += N'' the related requests of a1 should be a8 only (got '' + CAST(@n AS nvarchar(10)) + N'' of a8 and '' + CAST(@n2 AS nvarchar(10)) + N'' others of ours);'';
    -- the route, the golden record, the checks
    DELETE FROM @d4; INSERT INTO @d4 EXEC app.usp_request_detail @request_id = @a8, @actor_email = @u_resp, @only_set = 4;
    SELECT @n = COUNT(*) FROM @d4 WHERE route_id = (SELECT route_id FROM app.change_request WHERE request_id = @a8) AND responsible_role IS NOT NULL AND accountable_role IS NOT NULL;
    IF @n <> 1 SET @txt += N'' the route row is missing or wrong;'';
    SELECT @eid = equipment_id, @cur = model FROM @h WHERE n = 1;
    DELETE FROM @d5; INSERT INTO @d5 EXEC app.usp_request_detail @request_id = @a8, @actor_email = @u_resp, @only_set = 5;
    SELECT @n = COUNT(*) FROM @d5 WHERE entity_type = N''EQUIPMENT'' AND equipment_number = (SELECT equipment_number FROM @h WHERE n = 1)
                                      AND ISNULL(field_current_value, N'''') = ISNULL(@cur, N'''') AND profit_center_name = @pc;
    IF @n <> 1 SET @txt += N'' the golden record row is wrong (the field''''s current value should be the heater''''s model number);'';
    DELETE FROM @d6; INSERT INTO @d6 EXEC app.usp_request_detail @request_id = @a8, @actor_email = @u_resp, @only_set = 6;
    SELECT @n = COUNT(*), @n2 = SUM(CASE WHEN check_status = N''PASS'' THEN 1 ELSE 0 END) FROM @d6;
    IF @n <> 6 OR @n2 <> 6 SET @txt += N'' the checks of a waiting request should be six PASS rows for its approver ('' + CAST(@n AS nvarchar(10)) + N'' rows, '' + CAST(@n2 AS nvarchar(10)) + N'' PASS);'';
    DELETE FROM @d6; INSERT INTO @d6 EXEC app.usp_request_detail @request_id = @a1, @actor_email = @u_resp, @only_set = 6;
    SELECT @n = COUNT(*), @n2 = SUM(CASE WHEN check_status = N''NOT_CHECKED'' THEN 1 ELSE 0 END) FROM @d6;
    IF @n <> 6 OR @n2 <> 6 SET @txt += N'' the checks of an approved request should be six NOT_CHECKED rows ('' + CAST(@n AS nvarchar(10)) + N'' rows, '' + CAST(@n2 AS nvarchar(10)) + N'' NOT_CHECKED);'';
    -- an unknown request is refused
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_detail @request_id = -1, @actor_email = @u_resp; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50301 SET @txt += N'' an unknown request gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50301);'';
    IF @txt = N'''' PRINT ''OK  Q6 detail: the request row, the three events in order, the one related request, the route, the golden record, six PASS checks (six NOT_CHECKED once closed) and a refused unknown request'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q6'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q6 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q7 notifications --------------------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    SELECT @n = COUNT(*) FROM app.notification WHERE recipient_email = @u_resp AND read_at_utc IS NULL;
    DELETE FROM @nt1; INSERT INTO @nt1 EXEC app.usp_notification_list @actor_email = @u_resp, @only_set = 1;
    SELECT @n2 = unread_count FROM @nt1;
    IF @n2 <> @n OR @n < 8 SET @txt += N'' the unread count is '' + CAST(@n2 AS nvarchar(10)) + N'' for '' + CAST(@n AS nvarchar(10)) + N'' stored (the group was told of eight requests);'';
    DELETE FROM @nt2; INSERT INTO @nt2 (notification_id, topic, request_id, request_ref, title, body, created_at_utc, is_read)
        EXEC app.usp_notification_list @actor_email = @u_resp, @limit = 3, @only_set = 2;
    SELECT @n3 = COUNT(*) FROM @nt2;
    IF @n3 <> 3 SET @txt += N'' a limit of 3 gave '' + CAST(@n3 AS nvarchar(10)) + N'' items;'';
    SELECT @n3 = COUNT(*) FROM @nt2 AS x JOIN @nt2 AS y ON x.ord + 1 = y.ord WHERE x.notification_id < y.notification_id;
    IF @n3 <> 0 SET @txt += N'' the notifications are not newest first;'';
    SELECT TOP (1) @id = notification_id FROM @nt2 ORDER BY ord;
    SELECT @n3 = COUNT(*) FROM @nt2 WHERE notification_id = @id AND request_ref IS NOT NULL AND LEN(title) > 0 AND LEN(body) > 0 AND is_read = 0;
    IF @n3 <> 1 SET @txt += N'' the newest notification lacks its request reference, title or body;'';
    -- marking one read (APP-8 will do it through a procedure; here by hand) lowers the count and sets is_read
    UPDATE app.notification SET read_at_utc = SYSUTCDATETIME() WHERE notification_id = @id;
    DELETE FROM @nt1; INSERT INTO @nt1 EXEC app.usp_notification_list @actor_email = @u_resp, @only_set = 1;
    SELECT @n3 = unread_count FROM @nt1;
    IF @n3 <> @n - 1 SET @txt += N'' after marking one read the count is '' + CAST(@n3 AS nvarchar(10)) + N'' (expected '' + CAST(@n - 1 AS nvarchar(10)) + N'');'';
    DELETE FROM @nt2; INSERT INTO @nt2 (notification_id, topic, request_id, request_ref, title, body, created_at_utc, is_read)
        EXEC app.usp_notification_list @actor_email = @u_resp, @limit = 50, @only_set = 2;
    SELECT @n3 = COUNT(*) FROM @nt2 WHERE notification_id = @id AND is_read = 1;
    IF @n3 <> 1 SET @txt += N'' the read notification does not say it is read;'';
    -- the requester was told about the return and the rejection; an outsider has nothing
    SELECT @n3 = COUNT(*) FROM app.notification WHERE recipient_email = @u_req AND topic IN (N''REQUEST_RETURNED'', N''REQUEST_REJECTED'', N''REQUEST_APPROVED'');
    DELETE FROM @nt2; INSERT INTO @nt2 (notification_id, topic, request_id, request_ref, title, body, created_at_utc, is_read)
        EXEC app.usp_notification_list @actor_email = @u_req, @limit = 50, @only_set = 2;
    SELECT @n = COUNT(*) FROM @nt2 WHERE topic IN (N''REQUEST_RETURNED'', N''REQUEST_REJECTED'', N''REQUEST_APPROVED'');
    IF @n3 < 3 OR @n <> @n3 SET @txt += N'' the requester should see the approval, the return and the rejection ('' + CAST(@n AS nvarchar(10)) + N'' listed, '' + CAST(@n3 AS nvarchar(10)) + N'' stored);'';
    DELETE FROM @nt1; INSERT INTO @nt1 EXEC app.usp_notification_list @actor_email = @u_none, @only_set = 1;
    SELECT @n = unread_count FROM @nt1;
    DELETE FROM @nt2; INSERT INTO @nt2 (notification_id, topic, request_id, request_ref, title, body, created_at_utc, is_read)
        EXEC app.usp_notification_list @actor_email = @u_none, @only_set = 2;
    SELECT @n2 = COUNT(*) FROM @nt2;
    IF @n <> 0 OR @n2 <> 0 SET @txt += N'' an outsider has notifications;'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_notification_list @actor_email = @u_resp, @limit = 0; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50321 SET @txt += N'' limit 0 gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50321);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_notification_list @actor_email = @u_resp, @limit = 51; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50321 SET @txt += N'' limit 51 gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50321);'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_notification_list @actor_email = N''system:merge''; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50322 SET @txt += N'' a system address gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50322);'';
    IF @txt = N'''' PRINT ''OK  Q7 notifications: unread count matches the table, a limit is honoured, newest first, a read one is marked and uncounted, the requester sees the outcome, an outsider nothing, three refusals'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q7'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q7 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q8 the request dialog''s options -------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    DELETE FROM @f1; INSERT INTO @f1 EXEC app.usp_request_form_options @actor_email = @u_req, @only_set = 1;
    SELECT @n = COUNT(*) FROM @f1 WHERE field_code = N''FIRED_UNFIRED'' AND allowed_value IN (N''FIRED'', N''UNFIRED'');
    SELECT @n2 = COUNT(*) FROM @f1 WHERE field_code = N''EQUIPMENT_USER_STATUS'' AND allowed_value IN (N''AVFS'', N''NOPE'', N''OPER'', N''DECM'');
    IF @n <> 2 OR @n2 <> 4 SET @txt += N'' the list values are wrong (fired/unfired '' + CAST(@n AS nvarchar(10)) + N'' of 2, status '' + CAST(@n2 AS nvarchar(10)) + N'' of 4);'';
    DELETE FROM @f2; INSERT INTO @f2 EXEC app.usp_request_form_options @actor_email = @u_req, @only_set = 2;
    SELECT @n = COUNT(*) FROM @f2 WHERE can_submit = 1 AND is_admin = 0;
    IF @n <> 1 SET @txt += N'' a registered requester should be able to submit and not be an admin;'';
    DELETE FROM @f3; INSERT INTO @f3 EXEC app.usp_request_form_options @actor_email = @u_req, @only_set = 3;
    SELECT @n = COUNT(*) FROM @f3 WHERE field_code IN (N''EQUIP_CLASS'', N''CLASS_TYPE'', N''OBJECT_TYPE'', N''FLOC_CLASS'') AND LEN(reason) > 0;
    SELECT @n2 = COUNT(*) FROM @f3;
    IF @n <> 4 OR @n2 <> 4 SET @txt += N'' an ordinary person should be told the four classification fields are admin-only ('' + CAST(@n AS nvarchar(10)) + N'' of 4, '' + CAST(@n2 AS nvarchar(10)) + N'' listed);'';
    -- and the procedure really refuses what the dialog hides
    SELECT @eid = equipment_id, @cur = equip_class FROM @h WHERE n = 8;
    SET @errno = NULL;
    BEGIN TRY
        EXEC app.usp_request_create @source_type = N''MANUAL'', @entity_type = N''EQUIPMENT'', @field_code = N''EQUIP_CLASS'', @new_value = N''T4 CLASS'',
            @reason = N''T4 reads'', @requested_by = @u_req, @equipment_id = @eid, @old_value = @cur, @emit_result = 0;
    END TRY
    BEGIN CATCH
        SET @errno = ERROR_NUMBER();
    END CATCH;
    IF @errno IS NULL OR @errno <> 50113 SET @txt += N'' the procedure did not refuse an admin-only field for an ordinary person ('' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'', expected 50113);'';
    -- an admin, and a person nobody has registered
    DELETE FROM @f2; INSERT INTO @f2 EXEC app.usp_request_form_options @actor_email = @u_admin, @only_set = 2;
    SELECT @n = COUNT(*) FROM @f2 WHERE can_submit = 1 AND is_admin = 1;
    DELETE FROM @f3; INSERT INTO @f3 EXEC app.usp_request_form_options @actor_email = @u_admin, @only_set = 3;
    SELECT @n2 = COUNT(*) FROM @f3;
    IF @n <> 1 OR @n2 <> 0 SET @txt += N'' an admin should submit, be an admin and have no blocked fields ('' + CAST(@n AS nvarchar(10)) + N'', '' + CAST(@n2 AS nvarchar(10)) + N'' blocked);'';
    DELETE FROM @f2; INSERT INTO @f2 EXEC app.usp_request_form_options @actor_email = @u_unreg, @only_set = 2;
    SELECT @n = COUNT(*) FROM @f2 WHERE can_submit = 0 AND is_admin = 0;
    IF @n <> 1 SET @txt += N'' an unregistered person should not be able to submit;'';
    SET @errno = NULL; BEGIN TRY EXEC app.usp_request_form_options @actor_email = N''system:de''; END TRY BEGIN CATCH SET @errno = ERROR_NUMBER(); END CATCH;
    IF @errno IS NULL OR @errno <> 50331 SET @txt += N'' a system address gave '' + ISNULL(CAST(@errno AS nvarchar(12)), N''no error'') + N'' (expected 50331);'';
    IF @txt = N'''' PRINT ''OK  Q8 dialog options: list values for the two LIST fields, an ordinary person may submit but not the four admin-only fields (and the procedure refuses them), an admin has none blocked, an unregistered person cannot submit'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q8'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q8 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q9 the requests on a heater ----------------------------------------------------------------------------- */
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    SELECT @eid = equipment_id FROM @h WHERE n = 1;
    DELETE FROM @e1; INSERT INTO @e1 EXEC app.usp_equipment_requests @equipment_id = @eid, @only_set = 1;
    SELECT @n = total_count FROM @e1;
    DELETE FROM @e2; INSERT INTO @e2 (request_id, request_ref, request_status, is_open, equipment_id, functional_location, field_code, field_label, source_label, requested_at_utc, other_open)
        EXEC app.usp_equipment_requests @equipment_id = @eid, @only_set = 2;
    SELECT @n2 = COUNT(*) FROM @e2;
    IF @n < 2 OR @n2 <> CASE WHEN @n > 100 THEN 100 ELSE @n END SET @txt += N'' the heater''''s requests: total '' + CAST(@n AS nvarchar(10)) + N'', listed '' + CAST(@n2 AS nvarchar(10)) + N'';'';
    SELECT @n = COUNT(*) FROM @e2 WHERE request_id IN (@a1, @a8);
    IF @n <> 2 SET @txt += N'' the list should hold a1 and a8 ('' + CAST(@n AS nvarchar(10)) + N'' of 2);'';
    -- open first: a8 (open) before a1 (approved)
    SELECT @n = COUNT(*) FROM @e2 AS x JOIN @e2 AS y ON x.request_id = @a1 AND y.request_id = @a8 AND x.ord < y.ord;
    IF @n <> 0 SET @txt += N'' the approved request comes before the open one;'';
    SELECT @n = COUNT(*) FROM @e2 AS x JOIN @e2 AS y ON x.ord + 1 = y.ord WHERE x.is_open = 0 AND y.is_open = 1;
    IF @n <> 0 SET @txt += N'' a closed request is listed before an open one;'';
    -- another heater''s request is not on this heater''s list; an unknown heater has nothing
    SELECT @n = COUNT(*) FROM @e2 WHERE request_id IN (@a2, @a3, @a4, @a5, @a6, @a7);
    IF @n <> 0 SET @txt += N'' requests of other heaters are listed;'';
    DELETE FROM @e1; INSERT INTO @e1 EXEC app.usp_equipment_requests @equipment_id = -5, @only_set = 1;
    SELECT @n = total_count FROM @e1;
    DELETE FROM @e2; INSERT INTO @e2 (request_id, request_ref, request_status, is_open, equipment_id, functional_location, field_code, field_label, source_label, requested_at_utc, other_open)
        EXEC app.usp_equipment_requests @equipment_id = -5, @only_set = 2;
    SELECT @n2 = COUNT(*) FROM @e2;
    IF @n <> 0 OR @n2 <> 0 SET @txt += N'' an unknown heater should have no requests ('' + CAST(@n AS nvarchar(10)) + N'', '' + CAST(@n2 AS nvarchar(10)) + N'');'';
    IF @txt = N'''' PRINT ''OK  Q9 requests on a heater: its own two requests, the open one first, none of other heaters, an unknown heater gives nothing'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q9'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q9 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- Q10 the rollback left nothing behind ----------------------------------------------------------------------- */
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
BEGIN TRY
    SET @checks += 1; SET @txt = N'''';
    SELECT @n = COUNT(*) FROM app.principal_identity WHERE user_email LIKE N''t4.%@example.test'';
    SELECT @n2 = COUNT(*) FROM app.change_request WHERE requested_by LIKE N''t4.%@example.test'';
    SELECT @n3 = COUNT(*) FROM app.notification WHERE recipient_email LIKE N''t4.%@example.test'';
    IF @n <> 0 OR @n2 <> 0 OR @n3 <> 0 SET @txt += N'' left behind: '' + CAST(@n AS nvarchar(10)) + N'' people, '' + CAST(@n2 AS nvarchar(10)) + N'' requests, '' + CAST(@n3 AS nvarchar(10)) + N'' notifications;'';
    IF EXISTS (SELECT 1 FROM app.group_membership WHERE user_email LIKE N''t4.%@example.test'') OR EXISTS (SELECT 1 FROM app.principal_role_assignment WHERE principal_key LIKE N''t4.%@example.test'')
        SET @txt += N'' a test membership or role assignment is still there;'';
    IF @txt = N'''' PRINT ''OK  Q10 the test rolled back completely: no test people, requests, notifications, memberships or role assignments remain'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL Q10'' + @txt; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL Q10 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

IF @fails = 0
    PRINT ''t_request_reads RESULT: ALL '' + CAST(@checks AS varchar(12)) + '' CHECKS PASS'';
ELSE
    PRINT ''t_request_reads RESULT: '' + CAST(@fails AS varchar(12)) + '' OF '' + CAST(@checks AS varchar(12)) + '' CHECK(S) FAILED'';
');

PRINT N'=== end of app4_2_request_reads_test ===';
